INSERT INTO profession_specializations (profession, name, description, heroic_skill) VALUES
    ((SELECT id FROM professions WHERE name = $val$Artisan$val$ LIMIT 1), $val$Blacksmith$val$, $val$Blacksmiths forge and repair the metal tools, weapons, and armor that keep a community working and defended.$val$, (SELECT id FROM skills WHERE name = $val$Master Blacksmith$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Artisan$val$ LIMIT 1), $val$Carpenter$val$, $val$Carpenters shape timber into strong tools, structures, and furnishings, joining careful measurements with practical labor.$val$, (SELECT id FROM skills WHERE name = $val$Master Carpenter$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Artisan$val$ LIMIT 1), $val$Tanner$val$, $val$Tanners turn hides into durable leather for armor and everyday goods, knowing the worth of every part of an animal.$val$, (SELECT id FROM skills WHERE name = $val$Master Tanner$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Bard$val$ LIMIT 1), $val$Default$val$, $val$A performer who turns music, stories, and charm into a living and a legacy.$val$, (SELECT id FROM skills WHERE name = $val$Musician$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Fighter$val$ LIMIT 1), $val$Default$val$, $val$A trained combatant prepared to make a living with weapons and discipline.$val$, (SELECT id FROM skills WHERE name = $val$Veteran$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Hunter$val$ LIMIT 1), $val$Default$val$, $val$A wilderness tracker who finds food, follows prey, and survives far from settled roads.$val$, (SELECT id FROM skills WHERE name = $val$Companion$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Knight$val$ LIMIT 1), $val$Default$val$, $val$An oath-bound warrior who serves a cause through training, duty, and arms.$val$, (SELECT id FROM skills WHERE name = $val$Guardian$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Mage$val$ LIMIT 1), $val$Animist$val$, $val$Animists draw magic from the spirits that inhabit every part of the natural world.$val$, NULL),
    ((SELECT id FROM professions WHERE name = $val$Mage$val$ LIMIT 1), $val$Elementalist$val$, $val$Elementalists command magic through the four elements that form the essence of all things.$val$, NULL),
    ((SELECT id FROM professions WHERE name = $val$Mage$val$ LIMIT 1), $val$Mentalist$val$, $val$Mentalists manifest magic through self-control, discipline, and the power cultivated within their own minds.$val$, NULL),
    ((SELECT id FROM professions WHERE name = $val$Mariner$val$ LIMIT 1), $val$Default$val$, $val$A sailor at home among waves, rivers, and lakes, whatever their place aboard a vessel.$val$, (SELECT id FROM skills WHERE name = $val$Sea Legs$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Merchant$val$ LIMIT 1), $val$Default$val$, $val$A trader who reads people, prices, and opportunities wherever goods can change hands.$val$, (SELECT id FROM skills WHERE name = $val$Treasure Hunter$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Scholar$val$ LIMIT 1), $val$Default$val$, $val$A seeker of sources and understanding, trained to connect scattered facts into useful knowledge.$val$, (SELECT id FROM skills WHERE name = $val$Intuition$val$ LIMIT 1)),
    ((SELECT id FROM professions WHERE name = $val$Thief$val$ LIMIT 1), $val$Default$val$, $val$A resourceful operator who acquires what others fail to guard, through guile, speed, or force.$val$, (SELECT id FROM skills WHERE name = $val$Backstabbing$val$ LIMIT 1));
